<?php
namespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;
class Measurement extends Model{use HasFactory;protected $fillable=['measurement_point_id','access_point_id','measurement_import_id','ssid','bssid_hash','rssi_dbm','download_mbps','upload_mbps','latency_ms','jitter_ms','packet_loss_percent','channel','frequency_band','noise_floor_dbm','source_type','collection_method','is_simulated','quality_flags','raw_payload','captured_at'];protected function casts():array{return ['is_simulated'=>'boolean','quality_flags'=>'array','raw_payload'=>'array','captured_at'=>'datetime','download_mbps'=>'decimal:3','upload_mbps'=>'decimal:3','latency_ms'=>'decimal:3','jitter_ms'=>'decimal:3','packet_loss_percent'=>'decimal:3'];}public function point(){return $this->belongsTo(MeasurementPoint::class,'measurement_point_id');}public function import(){return $this->belongsTo(MeasurementImport::class,'measurement_import_id');}}
